-- Assistant « CCG Flow » — étoffe la base FAQ avec des fiches « comment faire » couvrant les
-- fonctionnalités des principaux modules, pour fiabiliser les réponses (le moteur reste 100 % à base
-- de règles, sans IA). Additive & idempotente : chaque fiche n'est insérée que si sa question n'existe
-- pas déjà (anti-jointure sur la question) — donc rejouable sans doublon même en prod.
INSERT INTO assistant_faq (question, reponse, mots_cles, module_key, lien, ordre)
SELECT v.question, v.reponse, v.mots_cles, v.module_key, v.lien, v.ordre
FROM (VALUES
  -- ── Stock ───────────────────────────────────────────────────────────────────────────────────
  ('Comment enregistrer une entrée ou une sortie de stock ?', 'Ouvrez Stock → Saisie de mouvement, choisissez la business unit et l''entrepôt, indiquez le type (entrée ou sortie), le produit et la quantité, puis Enregistrer. Le stock et la valorisation sont mis à jour automatiquement.', 'stock mouvement entree sortie saisie enregistrer ajuster quantite entrepot', 'stock', '/stock/saisie-mouvement', 70),
  ('Comment faire un inventaire de stock ?', 'Allez dans Stock → Inventaires, créez un inventaire pour l''entrepôt concerné, saisissez les quantités comptées : l''application calcule les écarts et permet de régulariser le stock.', 'stock inventaire comptage ecart regularisation physique entrepot', 'stock', '/stock/inventaires', 71),
  ('Comment transférer du stock entre entrepôts ?', 'Dans Stock → Transferts, créez un transfert en choisissant l''entrepôt de départ, l''entrepôt d''arrivée, le produit et la quantité. Le stock est diminué d''un côté et augmenté de l''autre.', 'stock transfert entrepot deplacer entre magasin mouvement', 'stock', '/stock/transferts', 72),
  ('Comment consulter la valorisation du stock (CMP) ?', 'Ouvrez Stock → Valorisation pour voir la valeur du stock calculée au coût moyen pondéré (CMP), par produit et par entrepôt.', 'stock valorisation cmp cout moyen pondere valeur prix', 'stock', '/stock/valorisation', 73),
  ('Comment saisir le relevé de stock du jour ?', 'Allez dans Stock → Relevé du jour, choisissez la date et la business unit, puis saisissez les quantités : le relevé journalier remplace l''ancien « stock du jour ».', 'stock releve jour journalier saisie quotidien quantite', 'stock', '/stock/releve-jour', 74),
  -- ── Production ──────────────────────────────────────────────────────────────────────────────
  ('Comment suivre la production sur une période ?', 'Ouvrez Production → Suivi pour consulter les cumuls de production par période, avec le détail par produit fini.', 'production suivi cumul periode historique tonnage', 'production', '/production/suivi', 80),
  -- ── Demandes d''achat ─────────────────────────────────────────────────────────────────────────
  ('Comment ajouter les frais annexes à un devis d''achat ?', 'Sur un devis, saisissez les frais annexes (TVA, Freight, FOB, Transport, Autres) pour obtenir un coût complet comparable entre fournisseurs. Ils sont reportés sur la demande, le bon de commande et le PDF.', 'achat frais annexes tva freight fob transport devis cout complet fournisseur', 'achats', '/purchase-requests/frais', 90),
  ('Comment consulter le rapport des achats ?', 'Ouvrez Demandes d''achat → Rapport pour la vue consolidée des achats, avec le détail articles, frais et total.', 'achat rapport consolidation articles frais total synthese', 'achats', '/purchase-requests/rapport', 91),
  -- ── Ressources Humaines ───────────────────────────────────────────────────────────────────────
  ('Comment faire une demande de journaliers ?', 'Dans RH → Mes demandes → Journaliers, remplissez la grille hebdomadaire (jour × tâche) et soumettez. La demande part dans le circuit de validation (DAF puis RH).', 'rh journaliers temporaire manoeuvre grille hebdomadaire demande daf main oeuvre', 'rh', '/rh/demandes/journaliers/new', 100),
  ('Comment remplir une fiche d''évaluation annuelle ?', 'Ouvrez RH → Évaluation → Fiches, sélectionnez votre fiche et notez les compétences de 1 à 5. Le circuit enchaîne auto-évaluation, manager puis RH jusqu''à la finalisation.', 'rh evaluation annuelle fiche competence note auto manager finaliser bareme', 'rh', '/rh/evaluation/fiches', 101),
  ('Comment faire une demande de recrutement ?', 'Dans RH → Mes demandes → Recrutement, décrivez le poste et le besoin, puis soumettez pour validation.', 'rh recrutement embauche poste besoin recruter demande', 'rh', '/rh/demandes/recrutement/new', 102),
  ('Comment demander le passage d''un CDD en CDI ?', 'Dans RH → Mes demandes → CDD vers CDI, renseignez le salarié concerné et le motif, puis soumettez.', 'rh cdd cdi passage titularisation contrat demande', 'rh', '/rh/demandes/cdi/new', 103),
  ('Où voir mes demandes RH ?', 'Ouvrez RH → Mes demandes pour retrouver toutes vos demandes (absence, congé, journaliers, recrutement…) et leur statut.', 'rh mes demandes suivi statut absence conge liste', 'rh', '/rh/mes-demandes', 104),
  -- ── Commerce ────────────────────────────────────────────────────────────────────────────────
  ('Comment enregistrer un versement client ?', 'Allez dans Commerce → Versements → Nouveau, choisissez le commercial et le client, saisissez le montant et la date, puis Enregistrer.', 'commerce versement client paiement encaissement saisir nouveau montant', 'commerce', '/commerce/versements/new', 110),
  ('Comment créer un bon de commande commercial ?', 'Ouvrez Commerce → Bons de commande → Nouveau, choisissez le type et le grossiste, ajoutez les produits et quantités. Le circuit passe par le contrôle de gestion puis le stock.', 'commerce bon commande bdc grossiste yaourt divers client vehicule nouveau', 'commerce', '/commerce/commandes', 111),
  ('Comment définir les objectifs commerciaux ?', 'Dans Commerce → Objectifs, fixez les cibles par commercial et par période.', 'commerce objectif cible commercial mensuel periode', 'commerce', '/commerce/objectifs', 112),
  ('Comment importer les versements depuis Excel ?', 'Ouvrez Commerce → Import, téléversez le fichier Excel des versements : l''application contrôle et intègre les lignes.', 'commerce import excel versement fichier charger tableur', 'commerce', '/commerce/import', 113),
  ('Comment consulter les commissions des commerciaux ?', 'Allez dans Commerce → Commissions pour voir le calcul des commissions par commercial.', 'commerce commission commercial calcul remuneration prime', 'commerce', '/commerce/commissions', 114),
  -- ── Logistique ──────────────────────────────────────────────────────────────────────────────
  ('Comment enregistrer un plein de carburant ?', 'Ouvrez Logistique → Carburant → Nouveau plein, choisissez le véhicule et la station, saisissez le kilométrage et les litres. La consommation plein-à-plein et la détection de fraude sont calculées automatiquement.', 'logistique carburant plein gasoil essence station consommation fraude vehicule litre kilometrage', 'logistique', '/logistique/carburant', 120),
  ('Comment faire une autorisation de dépense ?', 'Dans Logistique → Dépenses → Nouvelle, décrivez la dépense et le montant, puis soumettez : le circuit enchaîne Opérations, Contrôle de gestion, DAF puis DGA. Un PDF est généré.', 'logistique depense autorisation operations daf dga circuit montant fiche', 'logistique', '/logistique/depenses', 121),
  ('Comment signaler une panne de véhicule ?', 'Ouvrez Logistique → Pannes pour déclarer une panne sur un véhicule et suivre sa réparation.', 'logistique panne vehicule reparation signaler declarer garage', 'logistique', '/logistique/pannes', 122),
  ('Comment remplir une checklist de véhicule ?', 'Dans Logistique → Checklists, sélectionnez le véhicule et renseignez les points de contrôle.', 'logistique checklist controle vehicule verification etat', 'logistique', '/logistique/checklists', 123),
  -- ── QHSE / Laboratoire ────────────────────────────────────────────────────────────────────────
  ('Comment saisir une analyse de laboratoire ?', 'Ouvrez QHSE → Analyses, créez une analyse, renseignez l''échantillon et les résultats par paramètre : la conformité aux seuils est évaluée automatiquement.', 'qhse analyse laboratoire labo resultat echantillon saisie parametre seuil', 'qhse', '/qhse/analyses', 130),
  ('Comment déclarer une non-conformité ?', 'Dans QHSE → Non-conformités → Nouvelle, décrivez le défaut constaté et suivez son traitement jusqu''à la clôture.', 'qhse non conformite nc defaut incident qualite declarer traitement', 'qhse', '/qhse/non-conformites', 131),
  ('Comment libérer un lot ?', 'Ouvrez QHSE → Libération pour valider la conformité d''un lot et autoriser sa mise à disposition.', 'qhse liberation lot validation conformite autoriser mise disposition', 'qhse', '/qhse/liberation', 132),
  ('Comment enregistrer un échantillonnage ?', 'Dans QHSE → Échantillonnage, enregistrez les prélèvements selon le plan d''échantillonnage.', 'qhse echantillonnage prelevement plan sampling echantillon', 'qhse', '/qhse/echantillonnage', 133),
  ('Comment contrôler une expédition ?', 'Ouvrez QHSE → Expéditions pour réaliser le contrôle qualité au chargement avant la sortie.', 'qhse expedition controle chargement camion sortie qualite', 'qhse', '/qhse/expeditions', 134),
  -- ── DSI (informatique) ────────────────────────────────────────────────────────────────────────
  ('Comment signaler un incident informatique ?', 'Ouvrez DSI → Signaler un incident, décrivez le problème (poste, application, urgence) et soumettez : un ticket est créé et suivi avec un SLA.', 'dsi informatique it incident ticket probleme bug panne ordinateur support signaler', 'dsi', '/dsi/signaler', 140),
  ('Où voir mes tickets informatiques ?', 'Dans DSI → Mes tickets, retrouvez vos tickets de support et leur statut.', 'dsi ticket mes suivi statut support informatique', 'dsi', '/dsi/mes-tickets', 141),
  ('Comment voir le matériel qui m''est affecté ?', 'Ouvrez DSI → Mon matériel pour consulter les équipements informatiques qui vous sont affectés.', 'dsi materiel equipement affecte ordinateur parc mon informatique', 'dsi', '/dsi/mon-materiel', 142),
  -- ── Comptabilité ──────────────────────────────────────────────────────────────────────────────
  ('Comment traiter un bon de commande en comptabilité ?', 'Ouvrez Comptabilité → Traitement → Bons de commande, sélectionnez le bon de commande d''achat et effectuez sa prise en charge (anti-double intégrée).', 'comptabilite traitement bon commande bdc prise charge achat comptable', 'comptabilite', '/comptabilite/traitement/bons-de-commande', 150),
  -- ── Outils ────────────────────────────────────────────────────────────────────────────────────
  ('Comment créer ma carte de visite ?', 'Ouvrez Outils → Carte de visite, remplissez vos informations (nom, fonction, téléphone…) et récupérez votre carte aux couleurs du groupe CCG.', 'outils carte visite generateur creer personnel coordonnees', 'outils', '/outils/carte-visite', 160),
  ('Comment créer ma signature e-mail ?', 'Ouvrez Outils → Signature, saisissez vos informations et copiez la signature générée dans votre messagerie.', 'outils signature email mail generateur creer messagerie', 'outils', '/outils/signature', 161),
  -- ── Général ─────────────────────────────────────────────────────────────────────────────────
  ('Comment changer la langue de l''application ?', 'Utilisez le sélecteur de langue (FR / EN) en haut de l''écran. Les documents générés (e-mails, PDF) restent en français.', 'langue francais anglais fr en changer interface traduction basculer', NULL, NULL, 170),
  ('Comment passer en thème clair ou sombre ?', 'Utilisez le bouton de thème en haut de l''écran pour basculer entre l''affichage clair et sombre. Votre choix est mémorisé sur l''appareil.', 'theme clair sombre nuit mode affichage couleur basculer', NULL, NULL, 171),
  ('Par où commencer dans l''application ?', 'Chaque métier a son menu dans la barre de navigation (Stock, Production, Commerce, Logistique, RH, QHSE, DSI…). Vos accès dépendent des droits qui vous sont attribués par le super_admin. Posez-moi « comment utiliser » suivi d''un module pour une vue d''ensemble.', 'utiliser application commencer aide debuter general demarrer navigation menu', NULL, NULL, 172)
) AS v(question, reponse, mots_cles, module_key, lien, ordre)
WHERE NOT EXISTS (SELECT 1 FROM assistant_faq f WHERE f.question = v.question);
